import{_ as a,C as n,o as r,c as o,a2 as s,E as i}from"./chunks/framework.CFuv5BrO.js";const b=JSON.parse('{"title":"Design & Tradeoffs","description":"Hearth product positioning, core tradeoffs, system architecture, execution chain, and definition of done.","frontmatter":{"title":"Design & Tradeoffs","description":"Hearth product positioning, core tradeoffs, system architecture, execution chain, and definition of done.","outline":[2,3]},"headers":[],"relativePath":"en/design/index.md","filePath":"en/design/index.md","lastUpdated":1793797632000}'),l={name:"en/design/index.md"};function d(c,e,p,h,u,m){const t=n("DocCardGrid");return r(),o("div",null,[e[0]||(e[0]=s(`<p class="eyebrow">DESIGN</p><h1 id="from-intent-to-reliable-tasks" tabindex="-1">From Intent to Reliable Tasks <a class="header-anchor" href="#from-intent-to-reliable-tasks" aria-label="Permalink to &quot;From Intent to Reliable Tasks&quot;">​</a></h1><p class="lead">Hearth is a single-user, self-hosted, long-running personal Agent OS. This page puts product positioning, key tradeoffs, system architecture, and completion criteria into one narrative: why Hearth exists, how it is designed, and what must be true before the work counts as complete.</p><h2 id="the-short-version" tabindex="-1">The Short Version <a class="header-anchor" href="#the-short-version" aria-label="Permalink to &quot;The Short Version&quot;">​</a></h2><blockquote><p><strong>Hearth is not trying to be a more talkative assistant. It makes personal digital labor durable, controllable, and verifiable.</strong></p></blockquote><ul><li>Users work with tasks, approvals, and artifacts, not the internal details of Workers, Harnesses, or token budgets.</li><li>The system owns task state, permissions, budgets, evidence, and recovery paths; models are replaceable execution capabilities.</li><li>Capability grows by stages, but every stage must deliver a usable vertical slice rather than only another layer of infrastructure.</li></ul><h2 id="product-positioning" tabindex="-1">Product Positioning <a class="header-anchor" href="#product-positioning" aria-label="Permalink to &quot;Product Positioning&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Definition</th></tr></thead><tbody><tr><td>User</td><td>One primary user, with up to a few trusted collaborators</td></tr><tr><td>Deployment</td><td>Local-first and self-hostable; personal files and credentials stay under the user&#39;s control by default</td></tr><tr><td>Work</td><td>A mix of research, writing, documents, email, calendar, code, data, web, and desktop work</td></tr><tr><td>First wedge</td><td>One high-frequency, low-external-risk, verifiable task family with a complete end-to-end loop</td></tr><tr><td>Product form</td><td>Tasks, approvals, artifacts, and notifications rather than an endless chat transcript</td></tr><tr><td>Explicit non-goals</td><td>Enterprise multi-tenancy, a public agent marketplace, unapproved high-risk automation, or a foundation-model race</td></tr></tbody></table><h3 id="what-it-is-not" tabindex="-1">What It Is Not <a class="header-anchor" href="#what-it-is-not" aria-label="Permalink to &quot;What It Is Not&quot;">​</a></h3><ul><li>Another coding agent;</li><li>A Codex wrapper that only forwards prompts;</li><li>A black box that gives every permission to a model;</li><li>A tool that requires daily maintenance of prompts, plugins, and workflows;</li><li>An enterprise IAM, audit, and multi-tenant platform.</li></ul><h2 id="core-tradeoffs" tabindex="-1">Core Tradeoffs <a class="header-anchor" href="#core-tradeoffs" aria-label="Permalink to &quot;Core Tradeoffs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tradeoff</th><th>Hearth&#39;s Choice</th><th>Why</th></tr></thead><tbody><tr><td>Tasks or chat</td><td>Center on task cards and completion evidence</td><td>Long tasks need state, budgets, approvals, and recovery; chat history is not a reliable source of truth</td></tr><tr><td>Where state lives</td><td>Event Log as the source of truth; interfaces are projections</td><td>Crashes, device changes, replay, and audit all need one factual chain</td></tr><tr><td>Who executes</td><td>Native, Codex, Connector, Browser, GUI, Document/Data, and Human side by side</td><td>Different tasks need different capabilities, risk levels, and token costs</td></tr><tr><td>Build or integrate</td><td>Build control, execution kernel, memory, verification, and experience; integrate models, sandboxes, browsers, and APIs</td><td>Control, authorization, evidence, and recovery are the moat; mature lower layers should be reused</td></tr><tr><td>External effects</td><td>Preview, approval, idempotency key, outbox, and Receipt</td><td>Email, writes, sharing, deletion, and desktop actions must be traceable, reconcilable, and recoverable</td></tr><tr><td>Where data lives</td><td>Single-user, local-first, and portable</td><td>Personal context, memory, and credentials should not leave the user&#39;s control by default</td></tr><tr><td>Memory and evolution</td><td>Memory must be explainable, correctable, and forgettable; skills must be evaluated, canaried, promoted, and rolled back</td><td>Accumulate experience without unbounded self-modification</td></tr><tr><td>How delivery advances</td><td>Capability gates and vertical increments, not calendar promises</td><td>Prove reliability before expanding scope; every stage can be paused, trialed, and rolled back</td></tr></tbody></table><h2 id="execution-chain" tabindex="-1">Execution Chain <a class="header-anchor" href="#execution-chain" aria-label="Permalink to &quot;Execution Chain&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User / CLI / Web / Mobile / IM</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>     Experience Plane       Task cards · approvals · artifacts · takeover</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>     Personal Gateway       identity · channels · devices · attention</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>      Control Plane         triggers · policy · mandate · scheduling · watchdog</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>     Durable Harness        task graph · budgets · lease · retry · recovery</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>      Executor Layer        Native · Codex · Connector · Browser</span></span>
<span class="line"><span>                            GUI · Document/Data · Human</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>    Execution Gateway       workspace · sandbox · network · credential broker</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span> Event Log / Artifacts / Receipts</span></span>
<span class="line"><span>       ↓                    ↓</span></span>
<span class="line"><span>  Memory OS            Evolution OS</span></span></code></pre></div><p>Every fact enters the Event Log; every external effect passes through authorization, idempotency, and a receipt; every interface state is rebuilt from projections rather than transient in-memory objects.</p><h2 id="system-composition" tabindex="-1">System Composition <a class="header-anchor" href="#system-composition" aria-label="Permalink to &quot;System Composition&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Plane</th><th>Responsibility</th></tr></thead><tbody><tr><td>Experience Plane</td><td>Task cards, approvals, artifacts, takeover, and notifications</td></tr><tr><td>Personal Gateway</td><td>Identity, channel normalization, device registration, and attention entry</td></tr><tr><td>Control Plane</td><td>Intent decisions, triggers, policy, mandate, scheduling, and watchdog</td></tr><tr><td>Durable Harness</td><td>Task graph, routing, budgets, leases, retries, and recovery</td></tr><tr><td>Executor Layer</td><td>One protocol for different executors and human takeover</td></tr><tr><td>Execution Gateway</td><td>Workspace, sandbox, network, browser, GUI, and Credential Broker</td></tr><tr><td>Memory / Evolution</td><td>Personal context, memory, skills, evaluation, promotion, and rollback</td></tr></tbody></table><p>Every plane cooperates through the Event Log. The first stage uses a modular monolith and a single writer rather than premature microservices; boundaries are enforced by interfaces, schemas, events, and tests.</p><h2 id="task-coverage-and-definition-of-done" tabindex="-1">Task Coverage and Definition of Done <a class="header-anchor" href="#task-coverage-and-definition-of-done" aria-label="Permalink to &quot;Task Coverage and Definition of Done&quot;">​</a></h2><p>Hearth covers communication, documents, research, code, data, web SaaS, desktop applications, and personal errands. Autonomy ranges from A0 suggestions and A1 controlled execution to A2 authorized execution and A3 supervised autonomy, configured separately by task family, source, device, amount, and time window.</p><p>“Done” is not a model saying “done.” It requires all of the following:</p><ul><li>A user-visible result and next step;</li><li>Persistent state, validators, and reproducible evidence;</li><li>Approval, idempotency key, and receipt for every external effect;</li><li>A visible failure reason plus a recovery entry point or explicit human takeover.</li></ul><p>See the <a href="/hearth-os/en/reference/">Appendix</a> and <a href="/hearth-os/en/reference/checklists.html">Default Checklists</a> for the full task coverage and completion rules.</p><h2 id="non-negotiable-boundaries" tabindex="-1">Non-Negotiable Boundaries <a class="header-anchor" href="#non-negotiable-boundaries" aria-label="Permalink to &quot;Non-Negotiable Boundaries&quot;">​</a></h2><ol><li>The Event Log is the only source of truth.</li><li>Every state root has one write authority.</li><li>Every external effect has an idempotency key, an approval or explicit exemption, and a Receipt.</li><li>Executors never read long-lived raw credentials directly.</li><li>Every task has a budget, deadline, and cancellation path.</li><li>Memory has provenance, sensitivity, conflict, and forgetting policies.</li><li>Skill changes require evaluation, canary, promotion, and rollback.</li><li>Every increment is a complete vertical slice: user result, interface, persistent state, real execution, verification, and recovery at the same time.</li></ol><h2 id="current-status" tabindex="-1">Current Status <a class="header-anchor" href="#current-status" aria-label="Permalink to &quot;Current Status&quot;">​</a></h2><p>Hearth is in the specification and planning stage. Product, architecture, security, evaluation, and delivery plans are defined; runnable implementation has not started. The next step is Stage 0: choose the first task wedge and complete a clickable prototype, protocol contracts, evaluation baseline, and real task fixtures.</p><h2 id="continue-reading" tabindex="-1">Continue Reading <a class="header-anchor" href="#continue-reading" aria-label="Permalink to &quot;Continue Reading&quot;">​</a></h2>`,28)),i(t,{columns:3,items:[{no:"01",title:"Architecture Details",text:"Start with the overall data flow, domain model, and durable execution.",link:"/en/architecture/overview"},{no:"02",title:"Delivery Route",text:"See how seven stages, 35 increments, and 140 work packages fit together.",link:"/en/delivery/"},{no:"03",title:"Appendix",text:"Consult engineering boundaries, risks, ADRs, terminology, checklists, and the archive.",link:"/en/reference/"}]})])}const g=a(l,[["render",d]]);export{b as __pageData,g as default};
